// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { recordClicks } from "./src/server/clicks/record";
import type { ClickMessage } from "./src/server/clicks/types";

export default {
  fetch: handler.fetch,
  // The click consumer (spec section 7). Throwing makes the Queue retry the whole batch;
  // recordClicks is idempotent by clickId, so a retried click is still counted once.
  async queue(batch, env) {
    await recordClicks(
      env.DB,
      batch.messages.map((m) => m.body),
    );
    batch.ackAll();
  },
} satisfies ExportedHandler<CloudflareEnv, ClickMessage>;
